SELECT sub0.time AS "time", (sub0.value) AS "sensor.ENERGY.Total" FROM (WITH t AS (SELECT m FROM generate_series(date_trunc('day', time_bucket('1h'::interval, '2026-01-01T00:00:00Z'::timestamptz, 'Europe/Berlin') - '1h'::interval - interval '2 hours') - interval '1 day', '2026-01-08T00:00:00Z'::timestamptz + 2 * '1h'::interval + interval '1 day', interval '1 day') day CROSS JOIN LATERAL generate_series(day, day + interval '1 day', interval '1 minute') m WHERE ((day) AT TIME ZONE 'Europe/Berlin' - (day) AT TIME ZONE 'UTC') <> ((day + interval '1 day') AT TIME ZONE 'Europe/Berlin' - (day + interval '1 day') AT TIME ZONE 'UTC') AND ((m) AT TIME ZONE 'Europe/Berlin' - (m) AT TIME ZONE 'UTC') <> ((m - interval '1 minute') AT TIME ZONE 'Europe/Berlin' - (m - interval '1 minute') AT TIME ZONE 'UTC')), r AS (SELECT "time", c0, c1 FROM (SELECT label AS "time", c AS c0, lead(c) OVER (ORDER BY c) AS c1 FROM (SELECT c, time_bucket('1h'::interval, c, 'Europe/Berlin') AS label, lag(time_bucket('1h'::interval, c, 'Europe/Berlin')) OVER (ORDER BY c) AS previous FROM (SELECT DISTINCT c FROM (SELECT l AT TIME ZONE 'Europe/Berlin' + d AS c FROM generate_series(time_bucket('1h'::interval, ('2026-01-01T00:00:00Z'::timestamptz) AT TIME ZONE 'Europe/Berlin' - '1h'::interval - interval '2 hours'), ('2026-01-08T00:00:00Z'::timestamptz) AT TIME ZONE 'Europe/Berlin' + 2 * '1h'::interval, '1h'::interval) l, (VALUES (interval '0'), (interval '-1 hour'), (interval '-30 minutes'), (interval '30 minutes'), (interval '1 hour')) v(d) WHERE (l AT TIME ZONE 'Europe/Berlin' + d) AT TIME ZONE 'Europe/Berlin' = l UNION ALL SELECT m FROM t UNION ALL SELECT c FROM t CROSS JOIN LATERAL generate_series(date_trunc('minute', t.m - (LEAST('1h'::interval, interval '1 day') + interval '1 hour')), t.m + (LEAST('1h'::interval, interval '1 day') + interval '1 hour'), CASE WHEN extract(epoch FROM '1h'::interval) % 60 = 0 THEN interval '1 minute' ELSE interval '1 second' END) c) k) k) l WHERE previous IS DISTINCT FROM label) r WHERE c1 IS NOT NULL), b AS (SELECT "time", c0, c1 FROM r WHERE "time" IN (SELECT "time" FROM r WHERE c1 > time_bucket('1h'::interval, '2026-01-01T00:00:00Z'::timestamptz, 'Europe/Berlin') AND c0 < '2026-01-08T00:00:00Z'::timestamptz AND '2026-01-01T00:00:00Z'::timestamptz < '2026-01-08T00:00:00Z'::timestamptz)), p AS ((SELECT "time", "sensor.ENERGY.Total" AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "sensor.ENERGY.Total" IS NOT NULL AND "time" < (SELECT min(c0) FROM b) ORDER BY "time" DESC LIMIT 1) UNION ALL (SELECT "time", "sensor.ENERGY.Total" AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "sensor.ENERGY.Total" IS NOT NULL AND "time" >= (SELECT min(c0) FROM b) AND "time" < (SELECT max(c1) FROM b)) UNION ALL (SELECT "time", "sensor.ENERGY.Total" AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "sensor.ENERGY.Total" IS NOT NULL AND "time" >= (SELECT max(c1) FROM b) ORDER BY "time" ASC LIMIT 1)), s AS (SELECT "time" AS t0, value AS v0, lead("time") OVER w AS t1, lead(value) OVER w AS v1, COALESCE(lead("time") OVER w, GREATEST("time", now())) AS t_end FROM (SELECT "time", avg(value)::double precision AS value FROM p GROUP BY 1) p WINDOW w AS (ORDER BY "time")), m AS (SELECT c0 AS k, 0 AS kind, "time" AS label, c1, NULL::timestamptz AS t0, NULL::double precision AS v0, NULL::timestamptz AS t1, NULL::double precision AS v1, NULL::timestamptz AS t_end FROM b UNION ALL SELECT t0, 1, NULL, NULL, t0, v0, t1, v1, t_end FROM s), n AS (SELECT *, count(*) FILTER (WHERE kind = 0) OVER o AS g, count(*) FILTER (WHERE kind = 1) OVER o AS h FROM m WINDOW o AS (ORDER BY k, kind)), q AS (SELECT k, kind, g, h, label, c1, t0, v0, t1, v1, t_end, first_value(label) OVER (PARTITION BY g ORDER BY k, kind) AS g_label, first_value(c1) OVER (PARTITION BY g ORDER BY k, kind) AS g_c1, first_value(t0) OVER (PARTITION BY h ORDER BY k, kind) AS h_t0, first_value(v0) OVER (PARTITION BY h ORDER BY k, kind) AS h_v0, first_value(t1) OVER (PARTITION BY h ORDER BY k, kind) AS h_t1, first_value(v1) OVER (PARTITION BY h ORDER BY k, kind) AS h_v1, first_value(t_end) OVER (PARTITION BY h ORDER BY k, kind) AS h_t_end FROM n), o AS (SELECT g_label AS "time", t0, v0, t1, v1, t0 AS a, LEAST(t_end, g_c1) AS e FROM q WHERE kind = 1 AND g > 0 AND t0 < g_c1 UNION ALL SELECT label, h_t0, h_v0, h_t1, h_v1, k, LEAST(h_t_end, c1) FROM q WHERE kind = 0 AND h > 0 AND h_t_end > k) SELECT "time", (SUM(v0 * extract(epoch FROM e - a)) / NULLIF(SUM(extract(epoch FROM e - a)), 0))::double precision AS value FROM o GROUP BY 1 ORDER BY 1 ASC) sub0